  id: "czca-a1-8x", brand: "Audi", model: "A1", generation: "8X (2010-2018) - Facelift", engineCode: "CZCA", profileId: "czca-a1-8x", displacement: "1,395 cc", power: "125 hp (92 kW)", torque: "200 Nm", fuelType: "Petrol (TFSI)", cylinders: 4, valves: 16, compression: "10.5:1", yearRange: "2014-2018",
  timingType: "Belt (Long-life, Glass fiber reinforced)", injectionType: "Direct Injection (High Pressure - 200 Bar)", engineLifespan: "250,000+ km (Robust EA211 architecture)", turboType: "Single Scroll (Integrated Manifold, Rear Mounted)", ecuType: "Bosch Motronic MED 17.5.21", euroStandard: "Euro 6", maxPowerStockInternals: "170 - 180 hp (Limited by tiny Turbo)",
  fuelConsumption: { city: "6.2 L/100km", highway: "4.2 L/100km", mixed: "4.9 L/100km", sporty: "8.0 L/100km" },
