  crossReferenceParts: [ { partName: "Water Pump / Thermal Module", category: "Cooling", oem: { brand: "Audi Genuine", code: "04E 121 600 P", approxPrice: "280 EUR" }, crossRef: { brand: "INA", code: "538 0363 10", approxPrice: "140 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=538036310", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Water+Pump+Module+Audi+1.4" }, note: "INA manufactures this complex module for VAG. Buying the INA box saves 50%." }, { partName: "Timing Belt Kit", category: "Engine", oem: { brand: "Audi Genuine", code: "04E 198 119", approxPrice: "180 EUR" }, crossRef: { brand: "Continental", code: "CT1167K1", approxPrice: "85 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=CT1167K1", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Timing+Belt+Kit+Audi+1.4" }, note: "Includes tensioner and idler rollers." }, { partName: "Ignition Coil", category: "Ignition", oem: { brand: "Audi Genuine", code: "04E 905 110 K", approxPrice: "65 EUR" }, crossRef: { brand: "Eldor", code: "R3516S00100", approxPrice: "32 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=R3516S00100", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Ignition+Coil+Audi+1.4" }, note: "Eldor is the superior OEM supplier for the EA211." }, { partName: "Spark Plug", category: "Ignition", oem: { brand: "Audi Genuine", code: "04E 905 601 B", approxPrice: "24 EUR" }, crossRef: { brand: "NGK", code: "PZKER7A8EGS", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=PZKER7A8EGS", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=NGK+PZKER7A8EGS" }, note: "These plugs are indexed. Torque is critical." }, { partName: "Turbo Wastegate Actuator", category: "Turbocharger", oem: { brand: "Audi Genuine", code: "04E 145 725 AB", approxPrice: "250 EUR" }, crossRef: { brand: "Mahle", code: "030 TC 11002 000", approxPrice: "130 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=030TC11002000", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Turbo+Actuator+Audi+1.4" }, note: "Mahle produces the electric actuator. Common failure point." }, { partName: "Oil Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "04E 115 561 H", approxPrice: "18 EUR" }, crossRef: { brand: "Mann-Filter", code: "W 712/95", approxPrice: "9 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=W71295", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Mann+W712/95" }, note: "Includes the correct high-pressure anti-drain back valve." }, { partName: "High Pressure Fuel Pump", category: "Fuel System", oem: { brand: "Audi Genuine", code: "04E 127 026 CDP", approxPrice: "350 EUR" }, crossRef: { brand: "Hitachi", code: "133072", approxPrice: "180 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=133072", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Hitachi+Fuel+Pump" }, note: "Hitachi supplies the fuel system for the EA211." }, { partName: "Clutch Kit (Manual)", category: "Transmission", oem: { brand: "Audi Genuine", code: "04E 141 016 K", approxPrice: "350 EUR" }, crossRef: { brand: "Sachs", code: "3000 950 094", approxPrice: "160 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=3000950094", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Sachs+Clutch+Kit" }, note: "Sachs manufactures the clutch for the MQ200 gearbox." }, { partName: "PCV Valve", category: "Engine", oem: { brand: "Audi Genuine", code: "04E 103 464 M", approxPrice: "90 EUR" }, crossRef: { brand: "Febi", code: "100788", approxPrice: "40 EUR", source: "Aftermarket", autodoclink: "https://www.autodoc.parts/search?keyword=100788", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=PCV+Valve+Audi+1.4" }, note: "Replaces the integrated oil separator diaphragm." }, { partName: "Front Brake Pads", category: "Brakes", oem: { brand: "Audi Genuine", code: "8X0 698 151", approxPrice: "110 EUR" }, crossRef: { brand: "ATE", code: "13.0470-7111.2", approxPrice: "55 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=13047071112", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=ATE+Brake+Pads+Ceramic" }, note: "ATE Ceramic pads to eliminate brake dust." }, { partName: "Lambda Sensor (Pre-Cat)", category: "Sensors", oem: { brand: "Audi Genuine", code: "04E 906 262", approxPrice: "210 EUR" }, crossRef: { brand: "Bosch", code: "0 258 027 063", approxPrice: "95 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=0258027063", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Bosch+Oxygen+Sensor" }, note: "Bosch is the original manufacturer for the wideband sensor." } ],
