  tuningPotential: [ { stage: "Stage 1", power: "170 - 175 hp", notes: "Safe and highly recommended ECU remap. Transforms the car. ACT can be mapped out if desired.", zeroToHundred: "7.6s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "185 - 190 hp", notes: "Requires a high-flow downpipe. The small stock turbo runs out of flow here.", zeroToHundred: "7.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "210 - 220 hp", notes: "Requires an IS12 or Hybrid Turbo upgrade. Upgraded clutch is mandatory.", zeroToHundred: "6.2s", hundredToTwoHundred: "17.5s" } ],
