  manualLightPositions: { headlights: { x: 0.55, y: -0.13, z: 1.7 }, taillights: { x: 0.56, y: -0.01, z: -1.71 } }, customLightNames: { headlights: ["Acar_audi_s1sportback_2014_Mesh_lod0M_LightCluster_High_Aphong3SG1_0"], taillights: ["Acar_audi_s1sportback_2014_Mesh_lod0M_LightCluster_High_Aphong3SG1_0"] },
  riskRating: 4, 
  author: "Audi A1 Clubsport Quattro (https://skfb.ly/p9Cz7) by Mona x Supercars is licensed under Creative Commons Attribution (http://creativecommons.org/licenses/by/4.0/).",drivingExperience: "The CPTA (EA211 ACT) offers a unique driving experience. It delivers a punchy 140hp and 250Nm of torque, making it feel like a much larger engine. Under light load, it shuts off cylinders 2 and 3 seamlessly to save fuel, giving you hybrid-like efficiency on the highway. The switch is barely noticeable, but you might feel a slight resonance. It's incredibly agile due to the lightweight aluminum block.", mechanicVerdict: "A fantastic engine that blends performance and extreme efficiency. The core EA211 architecture is highly reliable with its belt drive. The ACT system is generally robust, though the actuators can sometimes leak oil. The biggest weakness remains the plastic water pump module. Keep the oil fresh to ensure the delicate ACT solenoids function properly.", repairCostEstimate: "$650 - $850 / year",
  model3DHotspots: [{"label":"Timing Belt & Cam Actuators","x":-0.25,"y":0.15,"z":1.35,"critical":true,"details":"The CPTA features Active Cylinder Technology (ACT). The timing system synchronizes complex cam-shifting actuators that shut down cylinders 2 and 3 under light loads to save fuel."},{"label":"Front Brake Pads","x":0.87,"y":-0.39,"z":1.13,"critical":true,"details":"Crucial for active safety. The CPTA's 140hp output requires well-maintained braking components to arrest the vehicle efficiently."},{"label":"Spark Plugs (ACT Specific)","x":0.0,"y":0.25,"z":1.18,"critical":false,"details":"Ignition health is absolutely critical for the ACT system. Misfires or weak sparks will prevent the engine from smoothly transitioning between 2-cylinder and 4-cylinder modes."},{"label":"Air Filter Box","x":0.45,"y":0.2,"z":1.25,"critical":false,"details":"Clean intake air ensures that the sophisticated mass airflow sensors can accurately meter fuel during cylinder deactivation transitions."},{"label":"Turbocharger Unit","x":0.03,"y":-0.28,"z":-1.96,"critical":false,"details":"Provides forced induction. Operates dynamically to maintain boost pressure even when half the engine's exhaust gases are temporarily cut off during ACT mode."}],
  engineBayHotspots: [ { x: 0.5, y: 0.5, label: "Engine Oil Fill Cap", details: "Check underneath for thick yellow/white 'mayonnaise' residue.", critical: false }, { x: 0.2, y: 0.2, label: "Engine Oil Dipstick", details: "Check oil level regularly. Crucial for the ACT system hydraulics.", critical: true }, { x: 0.8, y: 0.2, label: "Coolant Expansion Tank", details: "CRITICAL: Monitor this fluid level meticulously. Any drop indicates the water pump is likely leaking.", critical: true } ],
  visualTechGuide: { views: [ { id: "top_engine_view", label: "Top Engine View", imageUrl: "/images/engines/cpta_top.jpg", hotspots: [ { x: 50, y: 20, title: "ACT Actuators", details: "Visible on top of the engine block." }, { x: 50, y: 80, title: "Rear Mounted Turbocharger", details: "The turbo is mounted at the very rear for better chassis weight distribution." } ] } ] }
